  bool CaptureEngineering(){try{TrainStrength.Validate(document);if(document.SharedHousing!=null&&new[]{document.SharedHousing.Wall,document.SharedHousing.Partition,document.SharedHousing.Clearance,document.SharedHousing.BoltDiameter}.Any(v=>!MechanismCad.Finite(v)))throw new Exception("Параметры общего корпуса должны быть конечными числами.");if(materialEditor!=null&&materialEditor.SelectedObject is TrainMaterial)MaterialLibrary.Validate((TrainMaterial)materialEditor.SelectedObject);return true;}catch(Exception ex){Error(ex.Message);return false;}}
  void EnsureMaterials(){if(document.Materials==null)document.Materials=new TrainMaterialSettings();}
  void StrengthReport(bool csv){Calculate();if(solution==null||solution.Strength==null){Error("Сначала включите общий корпус и назначьте материалы или нагрузку.");return;}using(var d=new SaveFileDialog{Filter=csv?"CSV|*.csv":"Text|*.txt",FileName=csv?"Перегрузка.csv":"Перегрузка.txt"})if(d.ShowLocalizedDialog(this)==DialogResult.OK)ReleaseSupport.WriteText(d.FileName,TrainStrength.Report(solution.Strength,csv),System.Text.Encoding.UTF8);}
  static string Value(double? value,string unit){return value.HasValue?Engine.F(value.Value)+" "+unit:"Не определено";}
