ne.F(b.BendingStress)+" / "+Engine.F(b.TorsionStress));shaftTable.Rows.Add("Приведённое (Tresca), МПа",Engine.F(b.EquivalentStress));shaftTable.Rows.Add("Прогиб, мм",Value(b.Deflection,""));shaftTable.Rows.Add("Угол, рад",Value(b.Slope,""));shaftTable.Rows.Add("Запас по текучести",Value(b.YieldMargin,""));shaftTable.Rows.Add("Ресурс подшипников L10","Не определено: нет C и режима работы");if(document.Overload!=null&&document.Overload.ClutchEnabled){shaftTable.Rows.Add("Момент муфты, Н·м",Value(r.ClutchTorque,""));shaftTable.Rows.Add("Прижим муфты, Н",Value(r.SpringForce,""));}foreach(var m in r.Modes){var part=s.Scene.Model.Parts.FirstOrDefault(p=>p.Id==m.Part);var stage=document.Stages.FirstOrDefault(n=>n.Id==m.Part);int row=strengthTable.Rows.Add(I18n.T(m.Mode),part!=null?part.Label:stage!=null?stage.Name:m.Part,Value(m.LimitTorque,""),Value(m.Margin,""),I18n.T(m.Formula));strengthTable.Rows[row].Cells[1].ToolTipText=m.Part;strengthTable.Rows[row].Cells[4].ToolTipText=I18n.T(m.Note);}}
    overloadVisual=new OverloadVisualState{OutputPhase=phase};var leaf=CompoundReducer.Enabled(document)?CompoundReducer.Ordered(document).Last().Id:"";foreach(var pair in s.Scene.TrainMotions){bool output=document.Overload!=null&&document.Overload.ClutchEnabled?pair.Key=="SH_CLUTCH_OUTPUT":pair.Key.EndsWith("_SH_OUTPUT_CARRIER")||pair.Key.StartsWith(leaf+"_")&&pair.Key.Contains("OUTPUT_PIN");pair.Value.Visual=output?overloadVisual:null;}overloadTorque.Enabled=r!=null&&r.LimitTorque.HasValue;ApplyOverload();}finally{updatingEngineering=false;}}
  void ApplyOverload(){var s=engineeringSolution;if(s==null||s.Strength==null){if(overloadStatus!=null)overloadStatus.Text="Предел не определён. Назначьте материалы.";return;}var r=s.Strength;double torque=r.LimitTorque.HasValue?r.LimitTorque.Value*overloadTorque.Value/1000:0;bool enabled=document.Overload!=null&&document.Overload.Enabled;double? threshold=r.LimitTorque;if(document.Overload!=null&&document.Overload.ClutchEnabled&&r.ClutchTorque.HasValue)threshold=threshold.HasValue?Math.Min(threshold.Value,r.ClutchTorque.Value):r.ClutchTorque;overloadVisual.Enabled=enabled;overloadVisual.Failed=threshold.HasValue&&torque>threshold.Value;overloadVisual.Smooth=document.Overload!=null&&document.Overload.ClutchEnabled&&r.ClutchTorque.HasValue&&(!r.LimitTorque.HasValue||r.ClutchTorque<=r.LimitTorque);var colors=new Dictionary<string,Color>();foreach(var p in s.Scene.Model.Parts){var limits=r.Modes.Where(m=>m.Part==p.Id&&m.LimitTorque.HasValue).Select(m=>m.LimitTorque.Value).ToArray();if(!enabled||limits.Length==0||torque==0)continue;double margin=limits.Min()/torque;if(margin<2)colors[p.Id]=UiPalette.Get(margin<1?"Error":"Warning");}viewer.Scene.SetEngineeringColors(colors);var weak=r.Modes.Where(m=>m.Part==r.WeakestPart&&m.LimitTorque==r.LimitTorque).FirstOrDefault();overloadStatus.Text="Показ: "+Engine.F(torque)+" Н·м · предел ≈ "+Value(r.LimitTorque,"Н·м")+"\n"+(weak==null?"":I18n.T(weak.Mode)+" · "+(s.Scene.Model.Parts.FirstOrDefault(p=>p.Id==weak.Part)==null?weak.Part:s.Scene.Model.Parts.First(p=>p.Id==weak.Part).Label)+"\n")+(r.ClutchTorque.HasValue?"Муфта: "+Value(r.ClutchTorque,"Н·м")+" · прижим "+Value(r.SpringForce,"Н")+"\n":"")+"Схематичный показ, не моделирование разрушения.\nСкорость реального проскальзывания не определена."+(r.ClutchTorque.HasValue&&r.LimitTorque.HasValue&&r.ClutchTorque>r.LimitTorque?"\nМуфта выше предела слабого звена — защиты нет.":"");}
