 public sealed class ShaftLoadPanel:Panel {
  public TrainSolution Solution;public ShaftLoadPanel(){DoubleBuffered=true;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.Clear(UiPalette.Get("Field"));var s=Solution;if(s==null||s.Strength==null)return;var b=s.Strength.Shaft;float left=35,right=Width-25,baseY=Height*.35f,scale=(right-left)/(float)(b.Span+b.Overhang);float second=left+(float)b.Span*scale;using(var pen=new Pen(UiPalette.Get("Text"),2)){e.Graphics.DrawLine(pen,left,baseY,right,baseY);foreach(float x in new[]{left,second})e.Graphics.DrawPolygon(pen,new[]{new PointF(x,baseY),new PointF(x-7,baseY+14),new PointF(x+7,baseY+14)});}using(var pen=new Pen(UiPalette.Get("Error"),2)){e.Graphics.DrawLine(pen,right,baseY-28,right,baseY);e.Graphics.DrawLine(pen,right,baseY,right-5,baseY-8);}float plotY=Height*.65f;using(var pen=new Pen(UiPalette.Get("Accent"),2))e.Graphics.DrawLines(pen,new[]{new PointF(left,plotY),new PointF(second,plotY+35),new PointF(right,plotY)});TextRenderer.DrawText(e.Graphics,I18n.T("Вал на двух опорах · эпюра изгиба"),Font,new Rectangle(8,5,Width-16,35),UiPalette.Get("Text"));TextRenderer.DrawText(e.Graphics,"L="+Engine.F(b.Span)+" мм; a="+Engine.F(b.Overhang)+" мм; Mmax="+Engine.F(b.BendingMoment)+" Н·мм",Font,new Rectangle(8,Height-40,Width-16,38),UiPalette.Get("Muted"));}
 }
